Lemma tail_long_c : PMS.opnew_spec L HI ->
  forall (fx1 : FPState) R0 M0 model0 K LB cr ois os sp r s b R1 M1 model1 c n p l,
    PMIS.pre L HI R0 M0 model0 K LB cr ois os sp r s b ->
    PESCIS2.kont_c L HI R0 M0 model0 K LB cr ois sp r s b l ->
    Z.of_nat (length l) = PM.vs_size s -> L5.bytes_at RSEGS M0 (PM.vs_data os s) l ->
    s = PM.VLong c n p ->
    PMIS.mid L HI R0 M0 model0 LB cr ois os sp s b R1 M1 model1 ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 0x35404 M1 model1) K.
Proof.
